// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/sUSDMEscrow.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/MonetrixVault.sol";
import "../src/governance/MonetrixAccessController.sol";

// ATTACK TIMELINE:
// 1. [Setup] User deposits USDC into vault to get USDM, then deposits USDM into sUSDM to get shares.
// 2. [T=0] User calls sUSDM.cooldownShares() to initiate unstake, burning sUSDM and moving USDM to sUSDMEscrow.
// 3. [T=cooldown+1] Cooldown period expires. User is now eligible to claim.
// 4. [T=cooldown+2] Guardian pauses USDM contract due to an emergency.
// 5. [T=cooldown+3] User attempts to call sUSDM.claimUnstake(), which calls sUSDMEscrow.release(), which calls USDM.transfer().
// 6. [Assert] The claimUnstake transaction reverts because USDM is paused, freezing the user's funds in the escrow.

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        address user = address(0x1234);
        vm.deal(user, 100 ether);

        // 1. Setup: User deposits into vault to get USDM
        _deposit(user, 10_000e6); 

        sUSDM susdmToken = sUSDM(vault.susdm());
        sUSDMEscrow escrow = sUSDMEscrow(susdmToken.escrow());

        // User deposits USDM into sUSDM to get shares
        vm.startPrank(user);
        usdm.approve(address(susdmToken), type(uint256).max);
        uint256 usdmBal = usdm.balanceOf(user);
        uint256 shares = susdmToken.deposit(usdmBal, user);

        // 2. User initiates cooldown
        uint256 requestId = susdmToken.cooldownShares(shares);
        vm.stopPrank();

        // 3. Warp past cooldown
        uint256 cooldown = config.unstakeCooldown();
        vm.warp(block.timestamp + cooldown + 1);

        // 4. Guardian pauses USDM
        // Attempt to prank guardian. If guardian variable doesn't exist in base, 
        // we fallback to operator or acl admin.
        address guardianAddr = address(0);
        try this.getGuardian() returns (address g) {
            guardianAddr = g;
        } catch {
            guardianAddr = operator; // Fallback
        }

        vm.prank(guardianAddr);
        usdm.pause();

        // 5. User tries to claim
        vm.startPrank(user);
        vm.expectRevert(); // Reverts due to Pausable: paused in USDM._update()
        susdmToken.claimUnstake(requestId);
        vm.stopPrank();

        // 6. Assert funds are frozen in escrow
        uint256 escrowBal = usdm.balanceOf(address(escrow));
        assertGt(escrowBal, 0, "Funds are frozen in escrow due to USDM pause");
    }

    function getGuardian() external view returns (address) {
        return guardian;
    }
}
